 private function guard(int$a):void{if(rtrim($this->base,'/')!==self::TARGET)throw new \DomainException('TARGET_NOT_ALLOWED');$ok=(bool)$this->db->createCommand("SELECT COUNT(*) FROM `{$this->p}fm2_pilot_users` u JOIN `{$this->p}fm2_pilot_user_roles` ur ON ur.user_id=u.user_id JOIN `{$this->p}fm2_pilot_roles` r ON r.role_id=ur.role_id JOIN `{$this->p}fm2_pilot_role_permissions` rp ON rp.role_id=r.role_id WHERE u.user_id=:a AND u.status=1 AND BINARY u.activation_state='active' AND r.status=1 AND BINARY rp.permission='otiz.manage'",[':a'=>$a])->queryScalar();if(!$ok)throw new \DomainException('FORBIDDEN');}
