 private function repriceReason(\Throwable$error):string{$safe=['PREMIUM_UNRESOLVED','LIFT_TYPE_UNRESOLVED','PREMIUM_BAND_UNRESOLVED','SHAFT_UNRESOLVED','OBJECT_SOURCE_MISSING','CERTIFICATE_EVIDENCE_INVALID','RECLAMATION_EVIDENCE_INVALID','DEADLINE_EVIDENCE_ABSENT','ADMISSION_SNAPSHOT_MISSING'];$message=$error->getMessage();return in_array($message,$safe,true)?$message:match(true){$error instanceof \ValueError=>'SOURCE_VALUE_INVALID',$error instanceof \TypeError=>'SOURCE_TYPE_INVALID',$error instanceof \DomainException=>'SOURCE_DOMAIN_INVALID',default=>'PROJECTION_UNAVAILABLE'};}
